import sys, ezdxf
src = sys.argv[1]
x0, y0, x1, y1 = map(float, sys.argv[2:6])
doc = ezdxf.readfile(src)
msp = doc.modelspace()
def inside(*pts):
    return all(x0 <= p[0] <= x1 and y0 <= p[1] <= y1 for p in pts)
def walk(layout, depth=0):
    for e in layout:
        t = e.dxftype()
        if t == 'INSERT':
            try:
                for ve in e.virtual_entities():
                    yield ve
            except Exception as ex:
                pass
        else:
            yield e
n = 0
for e in walk(msp):
    t = e.dxftype()
    if t == 'LINE':
        a, b = e.dxf.start, e.dxf.end
        if inside(a, b):
            print('L', e.dxf.layer, e.dxf.linetype, round(a[0], 2), round(a[1], 2), round(b[0], 2), round(b[1], 2))
    elif t == 'ARC':
        c = e.dxf.center
        if inside(c):
            print('A', e.dxf.layer, round(c[0], 2), round(c[1], 2), 'r', round(e.dxf.radius, 2), round(e.dxf.start_angle, 1), round(e.dxf.end_angle, 1))
    elif t == 'CIRCLE':
        c = e.dxf.center
        if inside(c):
            print('C', e.dxf.layer, round(c[0], 2), round(c[1], 2), 'r', round(e.dxf.radius, 2))
    elif t == 'POINT':
        p = e.dxf.location
        if inside(p):
            print('P', e.dxf.layer, round(p[0], 2), round(p[1], 2))
    elif t == 'TEXT':
        p = e.dxf.insert
        if inside(p):
            print('T', e.dxf.layer, round(p[0], 2), round(p[1], 2), e.dxf.text)

